from pathlib import Path

def safe_upload_path(upload_dir: str, filename: str) -> str:
    if not isinstance(upload_dir, str) or not isinstance(filename, str):
        raise TypeError("upload_dir and filename must be strings")
    if '\0' in filename:
        raise ValueError("filename contains null byte")
    upload_path = Path(upload_dir).resolve(strict=False)
    if Path(filename).is_absolute():
        raise ValueError("filename must not be an absolute path")
    candidate = upload_path.joinpath(filename).resolve(strict=False)
    try:
        candidate.relative_to(upload_path)
    except ValueError:
        raise ValueError("filename escapes upload directory")
    return str(candidate)
```
